package com.example.tracking.controller;import com.example.tracking.model.LifecycleEvent;import com.example.tracking.repository.LifecycleEventRepository;import io.swagger.v3.oas.annotations.Operation;import java.util.List;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/tracking/orders")public class TrackingController{private final LifecycleEventRepository repository;public TrackingController(LifecycleEventRepository repository){this.repository=repository;}@GetMapping("/{orderId}/events")@Operation(summary="Get the Kafka lifecycle event history for an order")public List<LifecycleEvent>events(@PathVariable String orderId){return repository.findByOrderIdOrderByOccurredAtAsc(orderId);}}
